		</div>
		<!-- draw the headers -->
		<table>
		<thead>
			<tr>
			{{#each headers}}
				<th>{{=$view.data}}</th>
			{{/each}}
			</tr>
		</thead><tbody>
			{{#each results}}
				<tr class="{{=$ctx.createZebraClasses($itemNumber)}}">
				{{#each values}}
					{{#if $view.data == '__EMPTY__VALUE__'}}
						<td></td>
					{{else}}
						{{* if (/.ipx$/.test($view.data)) { }}
							<td><a href="#" data-href="/peopleforms/mo4/ipix/ipix_frame.php?url={{* result += $view.data; }}" class="clickable fancybox toggle_panel">Photo Link</a></td>
						{{* } else if (/(.jpg$)|(.gif$)|(.png$)/i.test($view.data)) { }}
							<td><a href="#" data-href="{{* result += $view.data; }}" class="clickable fancybox toggle_panel">Image Link</a></td>
						{{* } else if (!(/^</.test($view.data)) ){ }}
							<td title="{{* result += $view.data; }}">{{* result += $view.data; }}</td>
						{{* } else { }}
							<td>{{* result += $view.data; }}</td>
